DO $$
DECLARE
    v_count integer;
    v_hash text;
BEGIN
    SELECT count(*) INTO v_count
      FROM catalog.housing_records
     WHERE dataset_version_id = '00000000-0000-4000-8000-000000000001';
    IF v_count <> 50 THEN
        RAISE EXCEPTION 'house-price-v1 must contain exactly 50 rows, found %', v_count;
    END IF;

    SELECT encode(public.digest(
        convert_to(
            'source_id,square_footage,bedrooms,bathrooms,year_built,lot_size,distance_to_city_center,school_rating,price' || E'\n' ||
            string_agg(
                source_id::text || ',' || square_footage::text || ',' || bedrooms::text || ',' ||
                to_char(bathrooms, 'FM999999999990.0') || ',' || year_built::text || ',' || lot_size::text || ',' ||
                to_char(distance_to_city_center, 'FM999999999990.000') || ',' ||
                to_char(school_rating, 'FM999999999990.000') || ',' ||
                to_char(price, 'FM9999999999999990.00'),
                E'\n' ORDER BY source_id
            ) || E'\n',
            'UTF8'
        ),
        'sha256'
    ), 'hex') INTO v_hash
      FROM catalog.housing_records
     WHERE dataset_version_id = '00000000-0000-4000-8000-000000000001';

    IF v_hash <> '941c3d0fecd13fb2494bd97ffed44427047da708f17de871ab09a8eae41e6548' THEN
        RAISE EXCEPTION 'canonical dataset hash mismatch: %', v_hash;
    END IF;
END;
$$;

